Object.assign(views,{balance:'Balance sheet',equity:'Changes in equity',reconcile:'Financial reconciliation'});
function bookType(k){return {pricing:'Net Sales Price',income:'Income statement',detail:'Expense break-up',balance:'Balance sheet',cashflow:'Cash-flow statement',equity:'Changes in equity'}[k]||k;}
function financialKind(c){const t=keyOf(c.B2||c.A2);return t==='statement of financial position'?'balance':t==='statement of cash flows'?'cashflow':t==='statement of changes in equity'?'equity':null;}
function parsePeriod(v){if(typeof v==='number'){const d=new Date(Math.round((v-25569)*86400000));return {year:d.getUTCFullYear(),month:d.getUTCMonth()};}const s=clean(v),m=s.match(/(January|February|March|April|May|June|July|August|September|October|November|December)[\s-]+(20\d{2})/i);return m?{year:+m[2],month:['january','february','march','april','may','june','july','august','september','october','november','december'].indexOf(m[1].toLowerCase())}:null;}
function validateFinancial(c,k){if(!clean(c.B1||c.A1))throw Error('Financial statement has no company name.');if(k==='equity'){if(!/share capital/i.test(c.B6||'')||!/retained earnings/i.test(c.C6||''))throw Error('Use the supplied changes-in-equity column layout.');if(!Object.entries(c).some(([a,v])=>/^A\d+$/.test(a)&&/^Balance as on /i.test(v)&&parsePeriod(v)))throw Error('No equity balance dates found.');}else{if(c.B5!=='Particulars'||!Object.keys(c).some(a=>/^[A-Z]+5$/.test(a)&&parsePeriod(c[a])))throw Error('Use the supplied financial-statement layout with dates on row 5.');const keys=k==='balance'?[[24,'Total Assets'],[49,'Total Equity and Liabilities']]:[[13,'Net cash inflow/(outflow) from operating activities'],[34,'Cash and cash equivalents at the year End']];for(const [r,l]of keys)if(keyOf(c['B'+r])!==keyOf(l))throw Error('Financial statement rows do not match the supplied template.');}}
async function addAttachedFinancials(saved){if(saved.financialAttachmentVersion===1)return saved;const books=await(await fetch('financial.json',{cache:'no-store'})).json(),next=structuredClone(saved),name=clean(books.balance.cells.B1),id=makeSbuId(name);if(!next.sbus[id])next.sbus[id]={name,books:{}};for(const [k,b]of Object.entries(books))if(!next.sbus[id].books[k])next.sbus[id].books[k]=b;next.financialAttachmentVersion=1;await persist(next);return next;}
function finBook(k){return portfolio.sbus[activeSbu]?.books[k];}
availableYears=function(){const years=[...records.income,...records.detail].map(x=>x.year);for(const k of ['balance','cashflow','equity']){const b=finBook(k);if(!b)continue;for(const [a,v]of Object.entries(b.cells)){if(k==='equity'?!/^A\d+$/.test(a):!/^[A-Z]+5$/.test(a))continue;const p=parsePeriod(v);if(p)years.push(p.year);}}return [...new Set(years)].sort((a,b)=>a-b);};
function fnum(v){return typeof v==='number'&&Number.isFinite(v)?v:null;}
function finColumn(k,year,month){const c=finBook(k)?.cells;if(!c)return null;for(let j=5;j<80;j++){const p=parsePeriod(c[col(j)+'5']);if(p?.year===year&&p.month===month)return col(j);}return null;}
function finCell(k,r,year,month){const column=finColumn(k,year,month);return column?column+r:null;}
function fv(k,r,month=+ids().at(-1),year=+state.year){const cell=finCell(k,r,year,month);return cell?fnum(finBook(k).cells[cell]):null;}
function strictSum(a){return a.length&&a.every(x=>x!==null)?a.reduce((x,y)=>x+y,0):null;}
function cf(r){if(r===33)return fv('cashflow',r,ids()[0]);if(r===34)return fv('cashflow',r);if(r===36)return ids().length===1?fv('cashflow',r):null;return strictSum(ids().map(m=>fv('cashflow',r,m)));}
function priorPeriod(){const m=ids()[0];return m===0?{year:+state.year-1,month:11}:{year:+state.year,month:m-1};}
function priorBalance(r){const p=priorPeriod();return fv('balance',r,p.month,p.year);}
const bsTotals={14:'Total non-current assets',22:'Total current assets',32:'Total shareholders’ equity',38:'Total non-current liabilities'};
function finLabel(k,r){return clean(finBook(k)?.cells['B'+r]||bsTotals[r]||'');}
function finLink(k,r,l){return `<button data-fin="${k}" data-finrow="${r}">${esc(l||finLabel(k,r))}</button>`;}
function balanceView(){if(!finBook('balance'))return panel('Balance sheet','No balance sheet supplied for this SBU.',empty());const current=fv('balance',22),liab=fv('balance',47),ratioValue=ratio(current,liab);const rows=[12,13,14,17,18,19,20,21,22,24,29,30,32,35,36,37,38,41,42,43,44,45,46,47,49,51];return `<div class="cards">${card('Total assets',money(fv('balance',24)),unit())}${card('Equity',money(fv('balance',32)),unit())}${card('Net working capital',money(sub(current,liab)),unit()+' · current assets less current liabilities')}${card('Current ratio',ratioValue===null?'—':num(ratioValue,2)+'×','Current assets / current liabilities')}</div>`+panel('Statement of financial position',`Closing snapshot: ${periodMonthLabel(ids().at(-1))}. Balance-sheet values are never added across months.`,table(['Particulars',`Closing (${unit()})`,'Opening of selected period','Movement'],rows.map(r=>{const format=r===51?v=>num(v,4):money,a=fv('balance',r),b=priorBalance(r);return[finLink('balance',r),format(a),format(b),format(sub(a,b))];})))+`<p class="source">Net asset value per share is in BDT per share. Opening means the preceding month-end, or December of the previous year for YTD.</p>`;}
function cashView(){if(!finBook('cashflow')&&!finBook('balance'))return panel('Cash & working capital','No cash-flow or balance-sheet data supplied for this SBU.',empty());const cash=fv('balance',21),ocf=cf(13),nwc=sub(fv('balance',22),fv('balance',47));let body=`<div class="cards">${card('Closing cash',money(cash),unit()+' · balance sheet snapshot')}${card('Operating cash flow',money(ocf),unit()+' · selected period')}${card('Net change in cash',money(cf(32)),unit()+' · selected period')}${card('Net working capital',money(nwc),unit())}</div><div class="grid">`;body+=panel('Cash-flow statement',`${period()} · signed cash flows in ${unit()}. Opening / closing balances use the start / end of the period.`,finBook('cashflow')?table(['Particulars','Amount'],[8,9,10,11,12,13,16,17,18,19,20,23,24,25,26,27,28,29,30,32,33,34].map(r=>[finLink('cashflow',r),money(cf(r))])):empty());body+=panel('Working capital & liquidity',`As at ${periodMonthLabel(ids().at(-1))} · ${unit()}`,finBook('balance')?table(['Particulars','Closing','Movement'],[17,18,19,20,21,22,43,47].map(r=>[finLink('balance',r),money(fv('balance',r)),money(sub(fv('balance',r),priorBalance(r)))])):empty());body+=panel('Monthly cash movement',`Year ${state.year} · ${unit()}. Cash-flow closing and balance-sheet cash are shown separately.`,table(['Month','Operating','Investing','Financing','Net cash change','CFS closing cash','BS closing cash'],months.map((m,i)=>[m,...[13,20,30,32,34].map(r=>money(fv('cashflow',r,i))),money(fv('balance',21,i))])),true);return body+'</div>';}
function cashQualityView(){if(!finBook('cashflow'))return panel('Profit & cash quality','No cash-flow statement supplied for this SBU.',empty());const ocf=cf(13),profit=val(67),margin=ratio(ocf,val(31)),free=sub(ocf,cf(16)===null||cf(17)===null?null:-(cf(16)+cf(17)));return `<div class="cards">${card('Operating cash flow',money(ocf),unit())}${card('Reported NPAT',money(profit),unit()+' · income master')}${card('OCF less NPAT',money(sub(ocf,profit)),unit())}${card('Operating cash / sales',pct(margin===null?null:margin*100),'OCF / net sales')}</div>`+panel('Profit and cash conversion','The operating cash-flow statement uses the direct method. A full non-cash earnings bridge is unavailable.',`<p>${ocf!==null&&profit!==null?`Operating cash flow is ${money(ocf)} ${unit()}, compared with a reported ${profit<0?'loss':'profit'} of ${money(Math.abs(profit))} ${unit()}. The difference is ${money(ocf-profit)} ${unit()}.`: 'Comparable profit and cash data are incomplete.'}</p><p>Cash after reported PPE and capital-work-in-progress payments: <strong>${money(free)} ${unit()}</strong>. This is operating cash flow plus the signed acquisition and CWIP cash flows; other investing activities are excluded.</p><p>Review Financial reconciliation for source differences before interpreting earnings quality.</p>`)+panel('Monthly profit vs cash',`${state.year} · ${unit()}`,table(['Month','NPAT (income master)','Operating cash','Difference'],months.map((m,i)=>{const p=val(67,'Actual','income',[i]),o=fv('cashflow',13,i);return[m,money(p),money(o),money(sub(o,p))];})));}
function equityClosing(month=+ids().at(-1),year=+state.year){const c=finBook('equity')?.cells;if(!c)return null;for(let r=7;r<=300;r++){if(!/^Balance as on /i.test(c['A'+r]||''))continue;const p=parsePeriod(c['A'+r]);if(p?.year===year&&p.month===month)return r;}return null;}
function eqValue(offset,column='E',month=+ids().at(-1),year=+state.year){const r=equityClosing(month,year);return r===null?null:fnum(finBook('equity').cells[column+(r+offset)]);}
function eqFlow(offset,column='E'){return strictSum(ids().map(m=>eqValue(offset,column,m)));}
function equitySourceWarning(){const signature=b=>JSON.stringify(Object.entries(b?.cells||{}).filter(([a,v])=>/^[BCDE]\d+$/.test(a)&&typeof v==='number').sort(([a],[b])=>a.localeCompare(b)));const current=signature(finBook('equity'));if(current==='[]')return '';const matches=Object.entries(portfolio.sbus).filter(([id,s])=>id!==activeSbu&&signature(s.books.equity)===current).map(([id,s])=>s.name);return matches.length?panel('Source review required','Identical equity figures across SBUs',`<p>This SBU’s supplied equity figures match ${matches.map(esc).join(', ')}. Figures are retained exactly as supplied. Review the original worksheets and the Reconciliation menu for differences against balance-sheet equity and income-statement profit.</p>`):'';}
function equityView(){if(!finBook('equity'))return panel('Changes in equity','No equity statement supplied for this SBU.',empty());const p=priorPeriod(),opening=eqValue(0,'E',p.month,p.year),closing=eqValue(0);return equitySourceWarning()+`<div class="cards">${card('Opening equity',money(opening),unit())}${card('Closing equity',money(closing),unit())}${card('Reported equity movement',money(sub(closing,opening)),unit())}${card('SCE profit after tax',money(eqFlow(-3)),unit()+' · retained as reported')}</div>`+panel('Statement of changes in equity',period()+' · '+unit()+'. Click a line to inspect source cells.',table(['Particulars','Share capital','Retained earnings','Other equity','Total'],[[null,'Opening balance'],[-4,'Prior period adjustment'],[-3,'Profit after tax'],[-2,'Cash dividend'],[-1,'Stock dividend'],[0,'Closing balance']].map(([offset,l])=>[`<button data-equity="${offset===null?'open':offset}">${l}</button>`,...['B','C','D','E'].map(c=>money(offset===null?eqValue(0,c,p.month,p.year):offset===0?eqValue(0,c):eqFlow(offset,c)))])))+`<p class="source">Blank component cells remain unavailable even when the source provides a numeric total. SCE profit is not substituted for income-master NPAT.</p>`;}
function reconciliationRows(){const opening=cf(33),net=cf(32),closing=cf(34),ocf=cf(13),investing=cf(20),financing=cf(30);return [['Balance-sheet equation',fv('balance',24),fv('balance',49),'Total assets vs total equity and liabilities'],['Cash-flow closing vs balance sheet',closing,fv('balance',21),'Selected end-month cash balances'],['Opening cash + net movement vs closing',strictSum([opening,net]),closing,'Selected-period cash roll-forward'],['Operating + investing + financing vs net change',strictSum([ocf,investing,financing]),net,'Selected-period cash-flow totals'],['Equity statement closing vs balance sheet',eqValue(0),fv('balance',32),'Selected end-month total equity'],['SCE profit vs income-master NPAT',eqFlow(-3),val(67),'Selected-period profit after tax'],['Equity opening + movements vs closing',strictSum([eqValue(0,'E',priorPeriod().month,priorPeriod().year),eqFlow(-4),eqFlow(-3),eqFlow(-2),eqFlow(-1)]),eqValue(0),'Equity roll-forward'],['Closing equity components vs reported total',strictSum(['B','C','D'].map(c=>eqValue(0,c))),eqValue(0),'Share capital + retained earnings + other equity']];}
function reconciliationView(){return panel('Financial reconciliation',`Differences in raw BDT. Source figures are preserved; no balancing entries are inserted. ${period()}.`,table(['Check','Source A','Source B','A − B','Basis'],reconciliationRows().map(([l,a,b,n])=>[l,num(a,2),num(b,2),num(sub(a,b),2),n])))+panel('Monthly profit reconciliation',`${state.year} · raw BDT. Compare the two source statements without adjusting reported profit.`,table(['Month','SCE profit','Income-master NPAT','Difference'],months.map((m,i)=>{const a=eqValue(-3,'E',i),b=val(67,'Actual','income',[i]);return[m,num(a,2),num(b,2),num(sub(a,b),2)];})))+panel('Monthly cash checks',`${state.year} · raw BDT. Small reported rounding differences remain visible.`,table(['Month','CFS closing','BS cash','Difference','Opening + net − closing'],months.map((m,i)=>{const a=fv('cashflow',34,i),b=fv('balance',21,i),roll=strictSum([fv('cashflow',33,i),fv('cashflow',32,i)]);return[m,num(a,2),num(b,2),num(sub(a,b),2),num(sub(roll,a),2)];})));}
function financialEvidence(k,r){const book=finBook(k),ms=k==='balance'?[ids().at(-1)]:r===33?[ids()[0]]:r===34?[ids().at(-1)]:ids();let rows=ms.map(m=>{const cell=finCell(k,r,+state.year,m);return [periodMonthLabel(m),(cell?book.sourceCells?.[cell]||cell:'—'),num(fv(k,r,m),4)];});if(k==='balance'){const p=priorPeriod();rows.unshift([months[p.month]+' '+p.year,book.sourceCells?.[finCell(k,r,p.year,p.month)]||finCell(k,r,p.year,p.month)||'—',num(fv(k,r,p.month,p.year),4)]);}$('evidenceBody').innerHTML=`<h2>${esc(finLabel(k,r))}</h2><p>${esc(book.name)} · ${esc(book.sheet)}</p>${table(['Period','Source cell','Raw BDT value'],rows)}`;$('evidence').showModal();}
function equityEvidence(offset){const book=finBook('equity'),p=priorPeriod(),points=offset==='open'?[p]:offset==='0'?[{year:+state.year,month:+ids().at(-1)}]:ids().map(m=>({year:+state.year,month:m}));const rows=points.map(p=>{const r=equityClosing(p.month,p.year),rr=r===null?null:r+(offset==='open'?0:+offset);return[months[p.month]+' '+p.year,...['B','C','D','E'].map(c=>rr===null?'—':c+rr+': '+num(fnum(book.cells[c+rr]),4))];});$('evidenceBody').innerHTML=`<h2>Equity source details</h2><p>${esc(book.name)} · ${esc(book.sheet)}</p>${table(['Month','Share capital','Retained earnings','Other equity','Total'],rows)}`;$('evidence').showModal();}
const financialBind=bind;bind=function(){financialBind();document.querySelectorAll('[data-fin]').forEach(e=>e.onclick=()=>financialEvidence(e.dataset.fin,+e.dataset.finrow));document.querySelectorAll('[data-equity]').forEach(e=>e.onclick=()=>equityEvidence(e.dataset.equity));};
const originalInsights=insights;insights=function(){let s=originalInsights();if(finBook('cashflow')){const flow=cf(13),cash=fv('balance',21),wc=sub(fv('balance',22),fv('balance',47));s+=`<div class="insight"><b class="n">CF</b><div><h3>Cash and liquidity</h3><p>Operating cash flow: ${money(flow)} ${unit()}. Closing cash: ${money(cash)} ${unit()}. Net working capital: ${money(wc)} ${unit()}.</p></div></div>`;const gap=sub(eqFlow(-3),val(67));if(gap!==null&&Math.abs(gap)>1)s+=`<div class="notice">Source reconciliation required: equity-statement profit differs from income-master NPAT by ${num(gap,2)} BDT for the selected period. See Financial reconciliation.</div>`;}return s;};
const previousNotes=notes;notes=function(){return panel('Financial statement sources','Additional files linked to the selected SBU.',table(['Statement','Workbook','Worksheet'],['balance','cashflow','equity'].map(k=>[bookType(k),esc(finBook(k)?.name||'Not supplied'),esc(finBook(k)?.sheet||'—')])))+panel('Financial statement coverage & limitations','Latest supplied attachment: Financial Statement Master.xlsx',`<p>The AGL attachment provides BS snapshots from December 2025 to September 2026, monthly cash flows for January–September 2026 and changes in equity for the same period.</p><p>Cash flows are summed for YTD. Balance-sheet and equity closing balances use the final selected month. Opening balances use the start of the selected period.</p><p>June profit differs between SCE and the income master. Small cash and equity differences are retained and shown in Financial reconciliation. Printed sign-off dates in the workbook precede its September reporting date; reporting-column dates govern this dashboard.</p><p>Older hidden schedules (including historical debtor, fixed-asset and trend schedules), unused error cells and unrelated salary data are excluded. No external workbook links are refreshed.</p><p>Batch uploads now accept the supplied BS, CFS and SCE layouts alongside income and break-up files. Each recognized worksheet is assigned separately to an SBU before import. Hidden legacy schedules are not imported.</p>`)+previousNotes();};
if(views[location.hash.slice(1)])state.view=location.hash.slice(1);
